s/imports/Context.sol", "data/contracts/2025_01_lauratoken/contracts/01_vulnerable_05641e33_pumptoken/sources/contracts/imports/ERC20.sol", "data/contracts/2025_01_lauratoken/contracts/01_vulnerable_05641e33_pumptoken/sources/contracts/imports/IERC20.sol", "data/contracts/2025_01_lauratoken/contracts/01_vulnerable_05641e33_pumptoken/sources/contracts/imports/Initializable.sol", "data/contracts/2025_01_lauratoken/contracts/01_vulnerable_05641e33_pumptoken/sources/contracts/imports/Ownable.sol", "data/contracts/2025_01_lauratoken/contracts/01_vulnerable_05641e33_pumptoken/sources/contracts/imports/SafeMath.sol", "data/contracts/2025_01_lauratoken/contracts/01_vulnerable_05641e33_pumptoken/sources/contracts/imports/Uniswap.sol", "data/contracts/2025_01_lauratoken/contracts/01_vulnerable_05641e33_pumptoken/sources/contracts/PumpToken.sol"], "source_hint": "AI extracted: The LAURA token contract has a function `removeLiquidityWhenKIncreases` which allows users to remove liquidity from the WETH/LAURA pair. The vulnerability lies in the fact that this function does not properly check the amount of LAURA tokens it is removing, allowing an attacker to drain all WETH from the pair by manipulating the K value.", "verification_status": "verified"}], "contracts_dir": "data/contracts/2025_01_lauratoken", "id": "2025_01_lauratoken", "metadata": {"ai_enabled": true, "ai_model": "gemini-2.5-flash-lite|gemini-2.5-flash-lite", "dataset_version": "1.0.0", "poc_parser_version": "1.0.0", "processed_at": "2026-04-10T06:30:59.781Z"}, "num_bytecode_contracts": 1, "num_contracts": 1, "num_source_contracts": 1, "num_verified_contracts": 1, "poc_code": "// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

import "forge-std/Test.sol";
import "../interface.sol";

// Happy New Year
// @KeyInfo - Total Lost : 12.340357077284305206 ETH (~$41.2K USD)
// Attacker : https://etherscan.io/address/0x25869347f7993c50410a9b9b9c48f37d79e12a36
