22_03_bacon/contracts/01_vulnerable_b8919522_transparentupgradeableproxy/sources/contracts/test/Proxiable.sol"], "source_hint": "AI extracted: The `Bacon` contract is vulnerable to reentrancy through its `lend` and `redeem` functions. The `uniswapV2Call` function in the attacker contract calls `bacon.lend` and `bacon.redeem` within the same transaction. After the `bacon.lend` call, the `tokensReceived` function is triggered twice, allowing the attacker to call `bacon.lend` again before the first `lend` operation is fully processed. This leads to an uncontrolled increase in the attacker's balance without a corresponding increase in the contract's total assets, allowing them to redeem more tokens than they deposited.", "verification_status": "proxy"}, {"abi_available": true, "address": "0x366049d336e73cfaf39c6a933780ca4c96ea084c", "artifact_dir": "data/contracts/2022_03_bacon/contracts/02_helper_366049d3_pool16", "bytecode_available": false, "chain": {"id": 1, "name": "Ethereum"}, "compiler_version": "v0.8.9+commit.e5eed63a", "contract_name": "Pool16", "explorer_url": "https://etherscan.io/address/0x366049d336e73cfaf39c6a933780ca4c96ea084c", "fetch_error": null, "is_verified": true, "proxy": {"admin_address": null, "implementation_address": null, "is_proxy": false, "proxy_type": null, "resolution_depth": 0, "resolved_at": "2026-04-10T06:32:53.587Z"}, "role": "helper", "source_available": true, "source_files": ["data/contracts/2022_03_bacon/contracts/02_helper_366049d3_pool16/sources/contracts/PoolCore/Pool16.sol", "data/contracts/2022_03_bacon/contracts/02_helper_366049d3_pool16/sources/contracts/Staking/IStaking.sol", "data/contracts/2022_03_bacon/contracts/02_helper_366049d3_pool16/sources/contracts/PropTokens/PropToken0.sol", "data/contracts/2022_03_bacon/contracts/02_helper_366049d3_pool16/sources/contracts/PoolUtils/PoolUtils0.sol", "data/contracts/2022_03_bacon/contracts/02_helper_366049d3_pool16/sources/contracts/PoolStakingRewards/PoolStakingRewards4.sol", "da