            (uint256 reserve0, uint256 reserve1,) = hodl_weth.getReserves();
            uint256 amountIn = getAmountIn(reserve1 - pairBalance, reserve0, reserve1);
            weth.transfer(address(hodl_weth), amountIn * slot8 / 1000);
            times += 1;
        }
    }
