racts": [{"abi_available": true, "address": "0xcd07a7695e3372acd2b2077557de93e667b92bd8", "artifact_dir": "data/contracts/2023_02_cowswap/contracts/01_vulnerable_cd07a769_swapguard", "bytecode_available": true, "chain": {"id": 1, "name": "Ethereum"}, "compiler_version": "v0.8.15+commit.e14f2714", "contract_name": "SwapGuard", "explorer_url": "https://etherscan.io/address/0xcd07a7695e3372acd2b2077557de93e667b92bd8", "fetch_error": null, "is_verified": true, "proxy": {"admin_address": null, "implementation_address": null, "is_proxy": false, "proxy_type": null, "resolution_depth": 0, "resolved_at": "2026-04-10T06:35:09.954Z"}, "role": "vulnerable", "source_available": true, "source_files": ["data/contracts/2023_02_cowswap/contracts/01_vulnerable_cd07a769_swapguard/sources/contracts/SwapGuard.sol", "data/contracts/2023_02_cowswap/contracts/01_vulnerable_cd07a769_swapguard/sources/@openzeppelin/contracts/token/ERC20/IERC20.sol", "data/contracts/2023_02_cowswap/contracts/01_vulnerable_cd07a769_swapguard/sources/@openzeppelin/contracts/utils/math/SafeCast.sol"], "source_hint": "AI extracted: The `SwapGuard.envelope` function allows users to specify an `allowedLoss`. If this value is set to `type(uint256).max`, it effectively disables any loss protection. The attacker in the POC exploits this by setting `allowedLoss` to `type(uint256).max` and then crafting a `transferFrom` call within the `interactions` array. This `transferFrom` call is designed to transfer DAI from the `GPv2Settlement` contract to the attacker's address (`address(this)`). Since there's no loss protection, the `envelope` function executes this transfer, allowing the attacker to drain DAI from the `GPv2Settlement` contract.", "verification_status": "verified"}], "contracts_dir": "data/contracts/2023_02_cowswap", "id": "2023_02_cowswap", "metadata": {"ai_enabled": true, "ai_model": "gemini-2.5-flash-lite|gemini-2.5-flash-lite", "dataset_version": "1.0.0", "poc_parser_version": "1.0.0", "processed_at": "2026