        NEU1.approve(address(CamelotRouter), type(uint256).max);
        CamelotRouter.swapExactTokensForTokensSupportingFeeOnTransferTokens(
            neu1Amount, 0, path2, address(this), address(this), block.timestamp + 30 minutes
